  function navbar(){if(['detail','editor','attachment','reminders','map'].includes(screen))return '';return `<nav class="bottom-nav" aria-label="App 導覽">${[['timeline','calendar','行程'],['search','search','搜尋'],['now','clock','現在'],['attachments','clip','附件'],['trip','home','旅程']].map(([s,i,l])=>`<button class="nav-button ${s===screen?'active':''} ${s==='now'?'now':''}" data-action="nav-${s}"><span class="nav-icon">${icon(i)}</span><span>${l}</span></button>`).join('')}</nav>`;}
  function dateStrip(map=false){const rs=allReminders().filter(activeReminder);return `<div class="date-strip ${dates().length>5?'long':''}">${dates().map(d=>`<button class="date-chip ${d===selectedDate?'active':''}" data-date="${d}" aria-label="${niceDate(d)}${d===selectedDate?'，已選取':''}">${shortDate(d)}<small>${map?`${eventsFor(d).length} 個點`:d===dateOf(now)?'今天':weekday(d)}${rs.some(m=>dateOf(m.trigger)===d)?icon('bell'):''}</small></button>`).join('')}</div>`;}
  function timeline(){
    const note=noteFor(),stay=stayFor();
    return `${dateStrip()}<div class="time-zone-strip">${icon('clock')}當日時間：${escape(zoneLabel())}</div><div class="daynote ${noteExpanded?'':'collapsed'}"><div class="note-text" data-action="toggle-note" role="button" tabindex="0"><strong>今日備註</strong><p>${escape(note?.text||'點鉛筆，新增今天的小提醒。')}</p></div>${btn(noteExpanded?'up':'chevron',noteExpanded?'收合備註':'展開備註','toggle-note')}${btn('bell','備註提醒','note-reminder','blue')}${btn('edit','編輯備註','note','blue')}</div><div class="timeline-area"><div class="timeline-scroll"><div class="timeline-canvas ${animatedDirection}" style="height:${TOTAL}px">${timelineItems()}</div></div>${stay?`<div class="stay-float"><div class="stay-card"><span class="stay-symbol">${icon('bed')}</span><div class="stay-copy" data-action="stay" role="button" tabindex="0"><small>今晚住宿</small><strong>${escape(stay.name)}</strong><p>${escape(stay.location?.address||'尚未設定地址')}</p></div><button class="stay-navigate" data-action="navigate-stay">${icon('map')}導航</button></div></div>`:''}<button class="fab" data-action="add-event" aria-label="新增行程">${icon('plus')}</button></div>`;
  }
  function timelineItems(){
    let html=Array.from({length:25},(_,h)=>`<div class="hour-line" style="top:${TOP+h*HOUR}px"></div><span class="hour-label" style="top:${TOP+h*HOUR+5}px">${h===24?'24:00':`${pad(h)}:00`}</span>`).join('');
    const events=eventsFor(),positions=layoutEvents(events);
    html+=events.map((e,i)=>{
      const start=dateOf(e.startLocalDateTime)===selectedDate?minute(e.startLocalDateTime):0,end=dateOf(e.endLocalDateTime)===selectedDate?minute(e.endLocalDateTime):1440,h=Math.max(42,(end-start)*HOUR/60-3),p=positions[i];
      const style=`${palette(e)};top:${TOP+start*HOUR/60}px;height:${h}px;left:calc(67px + (100% - 75px) * ${p.column}/${p.columns});width:calc((100% - 75px) / ${p.columns} - ${p.columns>1?3:0}px);right:auto`;
      return `<button class="event-card ${h<60?'short':''}" data-event="${escape(e.id)}" style="${style}" aria-label="${timeOf(e.startLocalDateTime)} ${escape(e.title)}"><span class="event-time">${timeOf(e.startLocalDateTime)}${e.flexibility==='FIXED'?icon('lock'):''}${e.attachmentIds?.length?icon('clip'):''}${reminderFor(e.id).some(activeReminder)?icon('bell'):''}</span><strong>${escape(e.title)}</strong><span class="location-subtitle">${escape(e.location?.name||'')}</span></button>`;
    }).join('');
    html+=allReminders().filter(activeReminder).filter(m=>dateOf(m.trigger)===selectedDate).map(m=>`<div class="reminder-line" style="top:${TOP+minute(m.trigger)*HOUR/60}px"><span role="button" tabindex="0" data-reminder-open="${escape(m.r.id)}">${icon('bell')}${timeOf(m.trigger)}</span></div>`).join('');
    if(dateOf(now)===selectedDate)html+=`<div class="now-line" style="top:${TOP+minute(now)*HOUR/60}px"><span>${timeOf(now)}</span></div>`;
    return html;
  }
  function layoutEvents(events){
    const positions=events.map(()=>({column:0,columns:1}));let group=[],end=-Infinity;
    function flush(){let max=1,ends=[];for(const i of group){const start=naive(events[i].startLocalDateTime);let col=ends.findIndex(e=>e<=start);if(col<0)col=ends.length;ends[col]=naive(events[i].endLocalDateTime);positions[i].column=col;max=Math.max(max,ends.length);}for(const i of group)positions[i].columns=max;}
    events.forEach((e,i)=>{const start=naive(e.startLocalDateTime),finish=naive(e.endLocalDateTime);if(start>=end){flush();group=[];end=-Infinity;}group.push(i);end=Math.max(end,finish);});flush();return positions;
  }
  function detail(){const e=eventById(selectedEvent);if(!e)return empty('calendar','這個行程已不存在');const p=categories[e.category]||categories.OTHER,refs=(e.attachmentIds||[]).map(attachmentById).filter(Boolean),duration=Math.round((naive(e.endLocalDateTime)-naive(e.startLocalDateTime))/60000),quick=naive(shift(e.startLocalDateTime,-30))>naive(now);return `<div class="page-scroll"><section class="surface"><div class="row top"><span class="detail-symbol" style="${palette(e)}">${icon(p.icon)}</span><div class="grow"><h3 class="detail-title">${escape(e.title)}</h3><p class="detail-range">${niceDate(dateOf(e.startLocalDateTime))}　${timeOf(e.startLocalDateTime)} – ${dateOf(e.startLocalDateTime)!==dateOf(e.endLocalDateTime)?`${niceDate(dateOf(e.endLocalDateTime))} `:''}${timeOf(e.endLocalDateTime)}<br>${escape(e.timeZoneId||data.trip.timeZoneId)}</p></div></div><div class="row" style="margin-top:14px"><span class="chip ${e.flexibility==='FIXED'?'blue':''}">${e.flexibility==='FIXED'?icon('lock'):''}${e.flexibility==='FIXED'?'固定行程':'彈性安排'}</span><span class="small muted">${duration} 分鐘</span></div></section><div class="action-row"><button class="primary" data-action="navigate-event">${icon('map')}導航</button><button class="secondary" data-action="ticket" ${refs.length?'':'disabled'}>${icon('file')}票券</button></div><section class="surface">${detailRow('pin','地點',e.location?.name||'尚未設定')}${detailRow('map','地址',e.location?.address||'尚未設定')}${detailRow('file','備註',e.notes||'暫無備註')}${e.location?.latitude!=null?detailRow('globe','座標',`${e.location.latitude.toFixed(5)}, ${e.location.longitude.toFixed(5)}`):''}</section><div class="section-heading"><h3>附件</h3><button class="text-button" data-action="pick-attachment">附件庫</button><button class="text-button" data-action="add-file">${icon('plus')}新增</button></div>${refs.length?refs.map(attachmentRow).join(''):'<p class="small muted">尚無附件</p>'}<div class="section-heading"><h3>提醒</h3><button class="text-button" data-action="quick-reminder">${quick?'前 30 分':'5 分後'}</button><button class="text-button" data-action="reminder-editor">${icon('plus')}其他</button></div>${reminderFor(e.id).map(m=>`<div class="surface row" style="padding:11px"><span class="detail-symbol" style="width:34px;height:34px;border-radius:50%;--fill:#e3f2fd;--accent:#1976d2">${icon('bell')}</span><div class="grow small">${escape(reminderDescription(m))}<small class="muted" style="display:block;font-size:10px">${niceDate(dateOf(m.trigger))} ${timeOf(m.trigger)} · ${activeReminder(m)?'等待提醒':m.runtime.status==='FIRED'?'已通知':'已過期／停用'}</small></div><button class="text-button red-text" data-delete-reminder="${escape(m.r.id)}">刪除</button></div>`).join('')}<button class="danger block" style="margin-top:16px" data-action="delete-event">刪除行程</button></div>`;}
  function detailRow(i,label,value){return `<div class="detail-row">${icon(i)}<div class="grow"><label>${label}</label><p>${escape(value)}</p></div></div>`;}
  function editor(){if(!draft)return '';const e=draft.event;return `<div class="page-scroll form"><form id="event-form"><label>類型</label><div class="selection-chips">${Object.entries(categories).map(([k,v])=>`<button type="button" class="selection-chip ${e.category===k?'selected green':''}" data-category="${k}">${v.name}</button>`).join('')}</div>${field('event-title','名稱',e.title,'text','required maxlength="100"')}<div class="two-col"><div>${field('event-date','開始日期',dateOf(e.startLocalDateTime),'date','required')}</div><div>${field('event-end-date','結束日期',dateOf(e.endLocalDateTime),'date','required')}</div></div><div class="two-col"><div><label>開始時間</label><button type="button" class="outline block" data-action="clock-start" id="clock-start-value">${icon('clock')}${timeOf(e.startLocalDateTime)}</button></div><div><label>結束時間</label><button type="button" class="outline block" data-action="clock-end" id="clock-end-value">${icon('clock')}${timeOf(e.endLocalDateTime)}</button></div></div><label>固定性</label><div class="selection-chips"><button type="button" class="selection-chip ${e.flexibility==='FIXED'?'selected':''}" data-flexibility="FIXED">${icon('lock')}固定</button><button type="button" class="selection-chip ${e.flexibility==='FLEXIBLE'?'selected':''}" data-flexibility="FLEXIBLE">彈性</button></div>${field('event-location','地點',e.location?.name||'')}${field('event-address','地址',e.location?.address||'')}<button type="button" class="secondary block" style="margin-top:10px" data-action="pick-location">${icon('pin')}在地圖上選點</button><div class="coordinate-preview" id="editor-coordinates" style="margin-top:8px">${e.location?.latitude!=null?`${e.location.latitude.toFixed(5)}, ${e.location.longitude.toFixed(5)}`:'尚未設定座標'}</div><label>時區</label><select name="event-zone">${zoneOptions(e.timeZoneId||'')}</select><label>備註</label><textarea name="event-notes">${escape(e.notes||'')}</textarea><div class="section-heading"><h3>附件</h3><button type="button" class="text-button" data-action="editor-attachment">${icon('clip')}選擇附件</button></div><div id="editor-attachment-label" class="small muted">${(e.attachmentIds||[]).map(attachmentById).filter(Boolean).map(a=>escape(a.displayName)).join('、')||'尚未連結附件'}</div><p class="inline-error hidden" id="event-error"></p><button class="primary block" type="submit" style="margin-top:20px">${icon('check')}儲存行程</button></form></div>`;}
  function zoneOptions(current,inherit=true){return `${inherit?`<option value="" ${!current?'selected':''}>沿用旅程主要時區</option>`:''}${['Europe/Paris','Europe/London','Asia/Taipei','Asia/Tokyo','Europe/Amsterdam','America/New_York','UTC',current].filter((x,i,a)=>x&&a.indexOf(x)===i).map(z=>`<option value="${escape(z)}" ${current===z?'selected':''}>${escape(z)}</option>`).join('')}`;}
  function attachmentRow(a){const missing=isMissing(a);return `<div class="attachment-row" data-attachment="${escape(a.id)}" role="button" tabindex="0"><span class="file-icon ${a.kind.toLowerCase()} ${missing?'missing':''}">${icon(a.kind==='URL'?'link':a.kind==='IMAGE'?'image':'pdf')}</span><div class="grow"><strong>${escape(a.displayName)}</strong><small ${missing?'class="red-text"':''}>${a.kind} · ${missing?'缺少檔案，點此重新連結':a.kind==='URL'?'網址連結':'本機可用'}</small></div><button class="favorite ${a.favorite?'active':''}" data-favorite="${escape(a.id)}" aria-label="${a.favorite?'取消常用':'設為常用'}">${icon('star')}</button>${icon('next')}</div>`;}
  function isMissing(a){return a.kind!=='URL'&&!fileData[a.filePath];}
  function attachments(){const list=data.attachments.filter(a=>attachmentFilter==='all'||(attachmentFilter==='favorite'?a.favorite:isMissing(a)));return `<div style="padding:0 14px;text-align:right"><button class="text-button" data-action="add-url">${icon('link')}新增連結</button></div><div class="tab-row">${[['all','全部',data.attachments.length],['missing','有問題',data.attachments.filter(isMissing).length],['favorite','常用',data.attachments.filter(a=>a.favorite).length]].map(([k,l,n])=>`<button data-attachment-filter="${k}" class="${attachmentFilter===k?'active':''}">${l} ${n||''}</button>`).join('')}</div><div class="tabs-content">${list.length?list.map(attachmentRow).join(''):empty('clip','這個分類目前沒有附件')}</div><button class="fab" data-action="add-file" aria-label="新增附件">${icon('plus')}</button>`;}
  function search(){return `<div class="search-box">${icon('search')}<input type="search" id="search-input" placeholder="搜尋行程、備註、住宿、附件" value="${escape(searchQuery)}" aria-label="搜尋關鍵字">${searchQuery?btn('close','清除搜尋','clear-search'):''}</div><div class="page-scroll search-results" id="search-results">${searchResults()}</div>`;}
  function searchResults(){const q=searchQuery.trim().toLocaleLowerCase();if(!q)return `<div class="info-banner">${icon('search')}試試「羅浮宮」或「巴黎」。搜尋會涵蓋整趟旅程。</div>${['羅浮宮','巴黎','示範'].map(q=>`<button class="selection-chip" data-search="${q}" style="margin:8px 6px 0 0;display:inline-flex">${icon('search')}${q}</button>`).join('')}`;const match=(...xs)=>xs.some(x=>String(x||'').toLocaleLowerCase().includes(q));const groups=[['行程',data.events.filter(e=>match(e.title,e.notes,e.location?.name,e.location?.address)),e=>result('calendar',e.title,`${shortDate(dateOf(e.startLocalDateTime))} ${timeOf(e.startLocalDateTime)} · ${e.location?.name||''}`,'event',e.id)],['今日備註',data.dayNotes.filter(n=>match(n.text)),n=>result('edit',n.text,niceDate(n.date),'note',n.id)],['住宿',data.accommodations.filter(s=>match(s.name,s.location?.address,s.notes)),s=>result('bed',s.name,s.location?.address||'','stay',s.id)],['附件',data.attachments.filter(a=>match(a.displayName,a.fileName,a.url)),a=>result(a.kind==='URL'?'link':'file',a.displayName,a.kind,'attachment',a.id)]];if(!groups.some(g=>g[1].length))return empty('search','找不到符合的結果','換一個關鍵字試試。');return groups.filter(g=>g[1].length).map(([title,items,renderItem])=>`<div class="section-heading"><h3>${title}</h3><small>${items.length}</small></div>${items.map(renderItem).join('')}`).join('');}
  function result(i,title,sub,type,rid){return `<div class="result-row" role="button" tabindex="0" data-result="${type}" data-result-id="${escape(rid)}"><span class="file-icon">${icon(i)}</span><div class="grow"><strong>${escape(title)}</strong><small>${escape(sub)}</small></div>${icon('next')}</div>`;}
  function reminderDescription(m){if(m.runtime.snoozed)return `已延後 ${m.runtime.snoozed} 分鐘`;return m.r.kind==='RELATIVE'?`行程開始前 ${m.r.offsetMinutes} 分鐘`:'指定時間提醒';}
  function reminders(){const list=allReminders(),filtered=list.filter(m=>reminderFilter==='all'||(reminderFilter==='cleanup'?cleanupReminder(m):reminderFilter==='snooze'?m.runtime.snoozed:reminderFilter==='relative'?m.r.kind==='RELATIVE'&&!m.runtime.snoozed:m.r.kind==='ABSOLUTE'&&!m.runtime.snoozed));return `<div class="page-scroll"><h3 style="font-size:17px;margin:0 0 5px">所有提醒</h3><p class="small muted" style="margin:0 0 8px">共 ${list.length} 筆 · ${list.filter(activeReminder).length} 個等待提醒</p><div class="filter-pills">${[['all','全部'],['relative','行程前'],['absolute','指定時間'],['snooze','延後'],['cleanup','可清理']].map(([k,l])=>`<button data-reminder-filter="${k}" class="${reminderFilter===k?'active':''}">${l}${k==='cleanup'?` ${list.filter(cleanupReminder).length}`:''}</button>`).join('')}</div>${reminderFilter==='cleanup'&&filtered.length?'<button class="danger block" data-action="cleanup-reminders" style="margin-bottom:12px">清理這些提醒紀錄</button>':''}${filtered.length?filtered.map(m=>`<article class="surface reminder-card"><div class="row top"><span class="detail-symbol">${icon('bell')}</span><div class="grow" data-reminder-open="${escape(m.r.id)}" role="button" tabindex="0"><h3>${escape(m.title)}</h3><p>${shortDate(dateOf(m.trigger))} ${timeOf(m.trigger)}</p><small>${escape(reminderDescription(m))}</small></div><span class="chip ${activeReminder(m)?'blue':'gray'}" style="font-size:9px;padding:4px 7px">${activeReminder(m)?'等待提醒':m.r.enabled===false?'已停用':m.runtime.status==='FIRED'?'已通知':'已過期'}</span></div><div class="chips"><span class="chip ${m.runtime.snoozed?'orange':'blue'}">${m.runtime.snoozed?'延後':m.r.kind==='RELATIVE'?'行程前':'指定時間'}</span><span class="chip gray">${m.type==='event'?'行程':'備註'}</span>${cleanupReminder(m)?'<span class="chip red">可清理</span>':''}</div><div class="reminder-tools"><span>${activeReminder(m)?'啟用':'提醒紀錄'}</span><button role="switch" aria-checked="${m.r.enabled!==false}" aria-label="啟用${escape(m.title)}提醒" class="switch ${m.r.enabled!==false?'on':''}" data-toggle-reminder="${escape(m.r.id)}"></button><button class="text-button" data-snooze="${escape(m.r.id)}" data-delay="5">延後 5 分</button><button class="text-button red-text" data-delete-reminder="${escape(m.r.id)}">刪除</button></div></article>`).join(''):empty('bell','這個分類目前沒有提醒','可從行程或今日備註新增。')}<button class="secondary block" data-action="notify">${icon('bell')}觸發示範通知</button></div>`;}
  function trip(){return `<div class="page-scroll"><section class="surface"><div class="row"><span class="detail-symbol" style="--fill:#e3f2fd;--accent:#1976d2">${icon('suitcase')}</span><div class="grow"><h3 style="font-size:19px;margin:0 0 4px">${escape(data.trip.name)}</h3><small class="muted">${data.trip.startDate} – ${data.trip.endDate}<br>${escape(data.trip.timeZoneId)}</small></div>${btn('edit','編輯旅程','edit-trip','blue')}</div><div class="metrics">${[[data.events.length,'行程'],[data.accommodations.length,'住宿'],[allReminders().length,'提醒'],[data.attachments.length,'附件']].map(([n,l])=>`<div class="metric"><b>${n}</b>${l}</div>`).join('')}</div></section><div class="section-heading"><h3>時間設定</h3></div><section class="surface"><div class="setting-row">${icon('clock')}<div class="grow"><small>主要時區</small><p>${escape(zoneLabel())}</p><small>${escape(data.trip.timeZoneId)}</small></div><button class="outline" data-action="time-zone">變更</button></div><div class="divider"></div><div class="setting-row">${icon('user')}<span class="small">裝置目前時區</span><small class="grow" style="text-align:right">${escape(Intl.DateTimeFormat().resolvedOptions().timeZone)}</small></div></section><div class="info-banner">${icon('check')}一般行程、住宿、備註與提醒使用主要時區，輸入的時間是當地時間。</div><div class="section-heading"><h3>資料交換</h3></div><div class="two-col"><button class="action-card" data-action="export">${icon('export')}<span><b>匯出旅程</b><small>.tabiframe · 含附件</small></span></button><button class="action-card" data-action="import">${icon('import')}<span><b>匯入旅程</b><small>預覽後取代目前內容</small></span></button></div><button class="text-button block" data-action="import-demo" style="margin-top:8px">先用另一份虛構旅程試試</button><div class="section-heading"><h3>住宿</h3><button class="text-button" data-action="add-stay">${icon('plus')}新增</button></div>${data.accommodations.map(s=>`<div class="result-row" data-stay="${escape(s.id)}" role="button" tabindex="0"><span class="detail-symbol" style="--fill:#e3f4f1;--accent:#26a69a">${icon('bed')}</span><div class="grow"><strong>${escape(s.name)}</strong><small>${shortDate(s.startDateInclusive)} – ${shortDate(s.endDateExclusive)}</small></div>${icon('next')}</div>`).join('')}<div class="section-heading"><h3>本機使用者</h3></div><form class="surface row" id="profile-form">${icon('user')}<div class="grow field"><input name="profile-name" value="${escape(profile)}" maxlength="40" aria-label="使用者名稱"></div><button class="text-button" type="submit">儲存</button></form><p class="tiny muted" style="text-align:center">本頁為虛構互動展示，重新體驗可還原所有修改。</p></div>`;}
  function render(direction=''){
    const views={timeline,detail,editor,search,attachments,reminders,trip,map:routeMap,attachment:attachmentDetail};
    $('#app').innerHTML=`${appbar()}<div class="app-content ${direction==='back'?'screen-back':direction?'screen-in':''}">${(views[screen]||timeline)()}</div>${navbar()}`;
    bindScreen();animatedDirection='';
  }
  function bindScreen(){
    const dateRow=$('.date-strip.long'),activeDate=$('.date-chip.active');if(dateRow&&activeDate)dateRow.scrollLeft=Math.max(0,activeDate.offsetLeft-dateRow.clientWidth/2+activeDate.offsetWidth/2);
    if(screen==='detail'){const e=eventById(selectedEvent),durationLabel=$('.chip + .small.muted');if(e&&durationLabel)durationLabel.textContent=`${eventDuration(e)} 分鐘`;if(e?.endTimeZoneId&&e.endTimeZoneId!==(e.timeZoneId||data.trip.timeZoneId))$('.detail-range')?.insertAdjacentHTML('beforeend',`<br>抵達：${escape(e.endTimeZoneId)}`);}
    if(screen==='timeline'){
      const scroller=$('.timeline-scroll'),initial=scrolls[selectedDate]??TOP+8*HOUR-90;scroller.scrollTop=initial;
      let last=scroller.scrollTop,anchor=last;
      scroller.addEventListener('scroll',()=>{const top=scroller.scrollTop;if(Math.abs(top-anchor)>9){$('.stay-float')?.classList.toggle('hidden',top>anchor&&top>10);anchor=top;}last=top;scrolls[selectedDate]=top;},{passive:true});
      bindTimelineDrag();bindDateSwipe();
    }
    if(screen==='map')bindMap();
    if(screen==='search')$('#search-input')?.addEventListener('input',e=>{searchQuery=e.target.value;$('#search-results').innerHTML=searchResults();});
    if(screen==='editor'){
      $('#event-form')?.addEventListener('submit',saveEventForm);
      $('[name="event-zone"]').insertAdjacentHTML('afterend',`<label for="event-end-zone">結束時區（跨時區交通適用）</label><select name="event-end-zone" id="event-end-zone">${zoneOptions(draft.event.endTimeZoneId||'')}</select>`);
    }
    if(screen==='trip')$('#profile-form')?.addEventListener('submit',e=>{e.preventDefault();profile=new FormData(e.target).get('profile-name').trim()||'Alex';toast('名稱已儲存');});
  }
