  function bindDateSwipe(){let start=null;const target=$('.timeline-area');target.addEventListener('pointerdown',e=>{if(!e.target.closest('button,.stay-float'))start={x:e.clientX,y:e.clientY};else if(e.target.closest('.event-card'))start={x:e.clientX,y:e.clientY};},{passive:true});target.addEventListener('pointerup',e=>{if(!start||drag?.active){start=null;return;}const dx=e.clientX-start.x,dy=e.clientY-start.y;start=null;if(Math.abs(dx)>65&&Math.abs(dx)>Math.abs(dy)*1.7){const all=dates(),i=all.indexOf(selectedDate),next=all[i+(dx<0?1:-1)];if(next){suppressClickUntil=performance.now()+400;selectDate(next);}}});}
