  function showMoveDialog(){const e=eventById(movePending?.id);if(!e)return;const start=shift(e.startLocalDateTime,movePending.delta),end=shift(e.endLocalDateTime,movePending.delta);showModal('移動這個行程？',`<p>${escape(e.title)}${e.flexibility==='FIXED'?'是固定行程，請確認預約時間也能調整。':'的日期與時長會保持一致。'}</p><div class="surface" style="margin:12px 0"><div class="small muted">原時間</div><p>${niceDate(dateOf(e.startLocalDateTime))} ${timeOf(e.startLocalDateTime)} – ${timeOf(e.endLocalDateTime)}</p><div class="small blue-text">調整後</div><p style="color:#1976d2;font-weight:650">${niceDate(dateOf(start))} ${timeOf(start)} – ${timeOf(end)}</p></div><div class="action-row"><button class="outline" data-action="cancel-move">取消</button><button class="primary" data-action="confirm-move">確認調整</button></div>`,true);}
  function startEditor(e=null){saveScroll();draft={isNew:!e,event:clone(e||{id:id(),title:'',startLocalDateTime:`${selectedDate}T16:00`,endLocalDateTime:`${selectedDate}T17:00`,category:'SIGHT',flexibility:'FLEXIBLE',location:{},notes:'',attachmentIds:[],reminders:[]})};go('editor',{eid:e?.id||null});}
  function collectDraft(){if(!draft||!$('#event-form'))return;const f=new FormData($('#event-form')),e=draft.event;e.title=f.get('event-title');e.startLocalDateTime=`${f.get('event-date')}T${timeOf(e.startLocalDateTime)}`;e.endLocalDateTime=`${f.get('event-end-date')}T${timeOf(e.endLocalDateTime)}`;e.location={...e.location,name:f.get('event-location'),address:f.get('event-address')};e.notes=f.get('event-notes');e.timeZoneId=f.get('event-zone')||null;e.endTimeZoneId=f.get('event-end-zone')||null;}
