  function showModal(title,body,center=false){modal=title;$('#overlay-root').innerHTML=`<div class="scrim ${center?'dialog-center':''}" data-scrim="true"><section class="sheet" role="dialog" aria-modal="true" aria-label="${escape(title)}"><span class="sheet-handle"></span><header class="sheet-header"><h3>${escape(title)}</h3>${btn('close','關閉','close-modal')}</header><div class="sheet-body">${body}</div></section></div>`;}
