  function renderNotification(m){$('#notification-root').innerHTML=`<aside class="notification"><div class="notification-head">${icon('bell')}TABIframe · 旅行提醒 <button data-action="hide-notification" aria-label="關閉通知">×</button></div><button class="notification-open" data-reminder-open="${escape(m.r.id)}"><h3>${escape(m.title)}</h3><p>${m.type==='event'?`${niceDate(dateOf(m.target.startLocalDateTime))} ${timeOf(m.target.startLocalDateTime)} – ${timeOf(m.target.endLocalDateTime)}<br>${escape(m.target.location?.name||'')}`:`${niceDate(m.date)} · 點一下查看今日備註`}<br>${escape(reminderDescription(m))}</p></button><div class="notification-actions"><button data-snooze="${escape(m.r.id)}" data-delay="5">延後 5 分鐘</button><button data-snooze="${escape(m.r.id)}" data-delay="30">延後 30 分鐘</button></div></aside>`;}
