  function attachmentDetail(){const a=attachmentById(selectedEvent);if(!a)return empty('clip','附件不存在');const linked=data.events.filter(e=>(e.attachmentIds||[]).includes(a.id));return `<div class="page-scroll"><div class="surface"><div class="row"><span class="file-icon ${a.kind.toLowerCase()}">${icon(a.kind==='URL'?'link':a.kind==='IMAGE'?'image':'pdf')}</span><div class="grow"><strong>${escape(a.displayName)}</strong><div class="tiny muted">${a.kind} · ${isMissing(a)?'缺少檔案':'示範附件'}</div></div><button class="favorite icon-button ${a.favorite?'blue':''}" data-favorite="${escape(a.id)}" aria-label="切換常用">${icon('star')}</button></div></div>${a.kind==='URL'?`<div class="surface">${detailRow('link','連結',a.url)}<button class="primary block" data-external="${escape(a.url)}">開啟外部網站 ${icon('export')}</button></div>`:isMissing(a)?`<div class="info-banner">${icon('info')}中繼資料仍保留，但附件檔案目前缺失。你可以重新連結一份測試檔。</div><button class="primary block" data-relink="${escape(a.id)}">${icon('clip')}重新連結檔案</button>`:a.kind==='IMAGE'?`<div class="surface"><img class="image-preview" src="${attachmentUrl(a)}" alt="示範城市散步圖"></div>`:a.id==='museum-ticket'||a.id==='cruise-ticket'?ticketHTML(a):`<iframe title="PDF 附件預覽" class="preview-frame" src="${attachmentUrl(a)}"></iframe>`}${!isMissing(a)&&a.kind!=='URL'?`<button class="secondary block" data-download-attachment="${escape(a.id)}" style="margin-top:10px">${icon('export')}下載附件</button>`:''}<div class="section-heading"><h3>關聯行程</h3><small>${linked.length}</small></div>${linked.map(e=>result('calendar',e.title,`${niceDate(dateOf(e.startLocalDateTime))} ${timeOf(e.startLocalDateTime)}`,'event',e.id)).join('')||'<p class="small muted">尚未連結行程</p>'}<button class="danger block" data-action="delete-attachment" style="margin-top:15px">刪除附件</button></div>`;}
