  function addUrl(){showModal('新增連結附件',`<form class="field" id="url-form">${field('url-name','顯示名稱','','text','required maxlength="100"')}${field('url-value','網址','https://','url','required')}<p class="inline-error hidden" id="url-error"></p><div class="action-row"><button type="button" class="outline" data-action="close-modal">取消</button><button type="submit" class="primary">儲存連結</button></div></form>`);$('#url-form').addEventListener('submit',ev=>{ev.preventDefault();const f=new FormData(ev.target),url=f.get('url-value');if(!safeUrl(url)){$('#url-error').textContent='請輸入 https:// 或 http:// 網址。';$('#url-error').classList.remove('hidden');return;}const a={id:id(),displayName:f.get('url-name').trim(),kind:'URL',url,favorite:false,sensitive:false};data.attachments.push(a);if(screen==='detail'){const e=eventById(selectedEvent);(e.attachmentIds??=[]).push(a.id);}closeModal();render();toast('連結已加入附件庫');});}
