  function routeMap(){return `${dateStrip(true)}<div class="map-note">${icon('map')}依時間連線，青綠色標記為住宿。</div><div class="map-wrapper">${mapSVG()}<div class="map-tools"><button data-action="map-overview" aria-label="地圖全覽">${icon('expand')}全覽</button><button data-action="map-in" aria-label="放大地圖">＋</button><button data-action="map-out" aria-label="縮小地圖">－</button></div><div class="map-credits">TABIframe · 城市位置示意，非導航路線</div></div><div class="map-points"><div class="section-heading"><h3>移動順序</h3><small>${eventsFor().filter(e=>e.location?.latitude!=null).length} 個地點</small></div>${eventsFor().map((e,i)=>routeRow(e,i)).join('')||empty('pin','今天還沒有行程')}${stayFor()?routeRow(stayFor(),-1):''}</div>`;}
  const bounds={west:2.278,east:2.373,north:48.898,south:48.839};
