  function unproject(x,y){return {latitude:bounds.north-y/540*(bounds.north-bounds.south),longitude:bounds.west+x/700*(bounds.east-bounds.west)};}
  function baseMap(){
    const blocks=Array.from({length:7},(_,r)=>Array.from({length:9},(_,c)=>`<rect x="${c*83-35+(r%2)*15}" y="${r*86-22}" width="${57+(c%3)*4}" height="${55+(r%2)*8}" rx="${8+c%4}" fill="${(c+r)%4===0?'#e1e8d8':'#e8e7df'}"/>`).join('')).join('');
    const roads=Array.from({length:9},(_,i)=>`<path d="M${i*95-100} -30 ${i*95+130} 600"/>`).join('')+Array.from({length:7},(_,i)=>`<path d="M-30 ${i*100+10} 750 ${i*90-60}"/>`).join('');
    return `<rect width="700" height="540" fill="#f3f1e9"/>${blocks}<g fill="none" stroke="#fff" stroke-width="12">${roads}</g><g fill="none" stroke="#dddcd5" stroke-width="1">${roads}</g><path d="M-30 400C70 410 95 250 190 285S280 450 380 375 405 290 510 337 630 473 750 340" stroke="#b1d8e6" stroke-width="39" fill="none"/><path d="M-30 400C70 410 95 250 190 285S280 450 380 375 405 290 510 337 630 473 750 340" stroke="#c5e5ee" stroke-width="22" fill="none"/><path d="m138 260 35 32m100 36 28 43m91-21 27 30m115-32 20 34" stroke="#fff" stroke-width="9"/><path d="M75 238 147 189 184 252 112 281zM299 273 355 248 383 287 325 311zM487 47 548 28 572 97 520 118z" fill="#cfe2c8"/><g fill="#8b9792" font-family="sans-serif" font-size="14" text-anchor="middle"><text x="380" y="205" letter-spacing="4" font-size="22" fill="#89968e">PARIS</text><text x="130" y="181" font-size="10">Champ de Mars</text><text x="343" y="252" font-size="10">Tuileries</text><text x="370" y="440" font-size="10">Saint-Germain</text><text x="505" y="88" font-size="10">Montmartre</text><text x="533" y="372" font-size="10">Le Marais</text><text x="278" y="393" font-size="11" fill="#6ca7be" transform="rotate(-20 278 393)">La Seine</text></g>`;
  }
  function mapSVG(picker=false){const pts=eventsFor().filter(e=>e.location?.latitude!=null),stay=stayFor();const line=pts.map(e=>{const p=project(e.location);return `${p.x},${p.y}`;}).join(' ');const transform=mapTransform();return `<svg class="city-map" id="${picker?'picker-map':'city-map'}" viewBox="0 0 700 540" preserveAspectRatio="xMidYMid slice" role="img" aria-label="巴黎城市示意圖"><g id="${picker?'picker-world':'map-world'}" class="map-world" transform="${picker?'':transform}">${baseMap()}${picker?'':`<polyline points="${line}" fill="none" stroke="white" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"/><polyline points="${line}" fill="none" stroke="#1976d2" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>${pts.map((e,i)=>{const p=project(e.location);return `<g class="map-marker" data-map-point="${escape(e.id)}" role="button" tabindex="0" aria-label="${i+1} ${escape(e.title)}" transform="translate(${p.x} ${p.y})"><circle r="17" fill="#00000016" cy="2"/><circle r="16" fill="${mapFocus===e.id?'#ee8b1e':'#1976d2'}" stroke="white" stroke-width="3"/><text text-anchor="middle" dy="5" fill="white" font-size="13" font-family="sans-serif" font-weight="700">${i+1}</text></g>`;}).join('')}${stay?.location?.latitude!=null?`<g class="map-marker" role="button" tabindex="0" data-map-point="stay:${escape(stay.id)}" aria-label="當晚住宿" transform="translate(${project(stay.location).x} ${project(stay.location).y})"><circle r="16" fill="#26a69a" stroke="white" stroke-width="3"/><path d="M-8 7V-7m0 10H9v4m-14-8h5v4m2-6h8v5" fill="none" stroke="white" stroke-width="2"/></g>`:''}`}</g></svg>`;}
  function mapTransform(){return `translate(${mapPan.x} ${mapPan.y}) translate(350 270) scale(${mapScale}) translate(-350 -270)`;}
  function routeRow(item,i){const isStay=i===-1,loc=item.location;return `<div class="route-row ${isStay?'stay':''} ${mapFocus===(isStay?'stay:':'')+item.id?'active':''}" data-map-row="${isStay?'stay:':''}${escape(item.id)}" role="button" tabindex="0"><span class="route-number ${mapFocus===item.id?'selected':''}">${isStay?icon('bed'):i+1}</span><time>${isStay?'':timeOf(item.startLocalDateTime)}</time><div class="grow"><strong>${isStay?'今晚住宿 · ':''}${escape(item.name||item.title)}</strong><small>${escape(loc?.name||loc?.address||'尚未設定地點')}${loc?.latitude==null?' · 缺少座標':''}</small></div><button class="navigate" aria-label="導航至${escape(item.name||item.title)}" data-navigate="${isStay?'stay:':''}${escape(item.id)}">${icon('navigate')}</button></div>`;}
  function focusMap(eid){const isStay=eid.startsWith('stay:'),item=isStay?data.accommodations.find(s=>s.id===eid.slice(5)):eventById(eid);if(item?.location?.latitude==null){toast('這個地點缺少座標，可在編輯行程中選點。');return;}mapFocus=eid;mapScale=2.6;const p=project(item.location);mapPan={x:(350-p.x)*mapScale,y:(270-p.y)*mapScale};updateMap();}
  function updateMap(){const w=$('#map-world');if(w)w.setAttribute('transform',mapTransform());$$('[data-map-point]').forEach(g=>{const circle=$$('circle',g).at(-1);if(circle)circle.setAttribute('fill',g.dataset.mapPoint===mapFocus?'#ee8b1e':g.dataset.mapPoint.startsWith('stay:')?'#26a69a':'#1976d2');});$$('[data-map-row]').forEach(row=>row.classList.toggle('active',row.dataset.mapRow===mapFocus));}
  function bindMap(){const svg=$('#city-map');svg.addEventListener('wheel',ev=>{ev.preventDefault();mapScale=Math.max(.8,Math.min(5,mapScale*(ev.deltaY>0?.88:1.12)));updateMap();},{passive:false});svg.addEventListener('pointerdown',ev=>{if(ev.target.closest('.map-marker'))return;mapPanGesture={x:ev.clientX,y:ev.clientY,pan:{...mapPan},scale:700/svg.getBoundingClientRect().width};svg.setPointerCapture(ev.pointerId);$('#map-world').classList.add('panning');});svg.addEventListener('pointermove',ev=>{if(!mapPanGesture)return;mapPan.x=mapPanGesture.pan.x+(ev.clientX-mapPanGesture.x)*mapPanGesture.scale;mapPan.y=mapPanGesture.pan.y+(ev.clientY-mapPanGesture.y)*mapPanGesture.scale;updateMap();});const end=()=>{mapPanGesture=null;$('#map-world')?.classList.remove('panning');};svg.addEventListener('pointerup',end);svg.addEventListener('pointercancel',end);}
  function pickLocation(){collectDraft();editorPoint=draft.event.location?.latitude!=null?{...draft.event.location}:null;showModal('在地圖上選點',`<p>點一下地圖，設定行程的位置。也能直接填入經緯度。</p><div class="point-picker" id="point-picker">${mapSVG(true)}<span class="picker-pin hidden" id="picker-pin"></span></div><form class="field" id="coordinate-form"><div class="two-col"><div>${field('latitude','緯度',editorPoint?.latitude??'48.8606','number','step="any" min="-90" max="90" required')}</div><div>${field('longitude','經度',editorPoint?.longitude??'2.3376','number','step="any" min="-180" max="180" required')}</div></div><button type="submit" class="primary block" style="margin-top:16px">${icon('check')}使用這個位置</button></form>`);$('#point-picker').addEventListener('click',ev=>{const svg=$('#picker-map'),p=svg.createSVGPoint();p.x=ev.clientX;p.y=ev.clientY;const c=p.matrixTransform(svg.getScreenCTM().inverse()),loc=unproject(c.x,c.y);$('#latitude').value=loc.latitude.toFixed(6);$('#longitude').value=loc.longitude.toFixed(6);const r=$('#point-picker').getBoundingClientRect(),scale=r.width/$('#point-picker').offsetWidth;$('#picker-pin').style.left=`${(ev.clientX-r.left)/scale}px`;$('#picker-pin').style.top=`${(ev.clientY-r.top)/scale}px`;$('#picker-pin').classList.remove('hidden');});$('#coordinate-form').addEventListener('submit',ev=>{ev.preventDefault();const f=new FormData(ev.target),lat=Number(f.get('latitude')),lng=Number(f.get('longitude'));if(!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>90||Math.abs(lng)>180)return;draft.event.location={...draft.event.location,latitude:lat,longitude:lng,coordinateSource:'MAP_TAP'};$('#editor-coordinates').textContent=`${lat.toFixed(5)}, ${lng.toFixed(5)}`;closeModal();toast('行程座標已設定');});}
  function stayEditor(sid=null){const existing=sid==='__new__'?null:(data.accommodations.find(s=>s.id===sid)||stayFor());const s=clone(existing||{id:id(),name:'',startDateInclusive:selectedDate,endDateExclusive:shift(`${data.trip.endDate}T00:00`,1440).slice(0,10),checkInTime:'15:00',checkOutTime:'11:00',location:{},notes:'',attachmentIds:[]});showModal('住宿資料',`<form class="field" id="stay-form">${field('stay-name','住宿名稱',s.name,'text','required maxlength="100"')}<div class="two-col"><div>${field('stay-start','入住日期',s.startDateInclusive,'date','required')}</div><div>${field('stay-end','退房日期',s.endDateExclusive,'date','required')}</div></div><div class="two-col"><div>${field('stay-checkin','入住時間',s.checkInTime||'15:00','time')}</div><div>${field('stay-checkout','退房時間',s.checkOutTime||'11:00','time')}</div></div>${field('stay-address','地址',s.location?.address||'')}${field('stay-contact','聯絡資訊',s.contact||'')}<div class="two-col"><div>${field('stay-lat','緯度',s.location?.latitude??'','number','step="any" min="-90" max="90"')}</div><div>${field('stay-lng','經度',s.location?.longitude??'','number','step="any" min="-180" max="180"')}</div></div><label>備註</label><textarea name="stay-notes">${escape(s.notes||'')}</textarea><p id="stay-error" class="inline-error hidden"></p><div class="action-row">${data.accommodations.some(x=>x.id===s.id)?`<button type="button" class="danger" data-delete-stay="${escape(s.id)}">刪除住宿</button>`:'<button type="button" class="outline" data-action="close-modal">取消</button>'}<button class="primary" type="submit">儲存</button></div></form>`);$('#stay-form').addEventListener('submit',ev=>{ev.preventDefault();const f=new FormData(ev.target);if(f.get('stay-end')<=f.get('stay-start')){$('#stay-error').classList.remove('hidden');$('#stay-error').textContent='退房日期必須晚於入住日期。';return;}if(Boolean(f.get('stay-lat'))!==Boolean(f.get('stay-lng'))){$('#stay-error').classList.remove('hidden');$('#stay-error').textContent='緯度與經度需要一起填寫。';return;}s.name=f.get('stay-name').trim();s.startDateInclusive=f.get('stay-start');s.endDateExclusive=f.get('stay-end');s.checkInTime=f.get('stay-checkin');s.checkOutTime=f.get('stay-checkout');s.location={...s.location,address:f.get('stay-address'),latitude:f.get('stay-lat')?Number(f.get('stay-lat')):null,longitude:f.get('stay-lng')?Number(f.get('stay-lng')):null};s.notes=f.get('stay-notes');s.contact=f.get('stay-contact');const i=data.accommodations.findIndex(x=>x.id===s.id);if(i<0)data.accommodations.push(s);else data.accommodations[i]=s;closeModal();render();toast('住宿資料已儲存');});}
  function editTrip(){showModal('編輯旅程',`<form class="field" id="trip-form">${field('trip-name','旅程名稱',data.trip.name,'text','required maxlength="80"')}<div class="two-col"><div>${field('trip-start','開始日期',data.trip.startDate,'date','required')}</div><div>${field('trip-end','結束日期',data.trip.endDate,'date','required')}</div></div><p id="trip-error" class="inline-error hidden"></p><div class="action-row"><button class="outline" type="button" data-action="close-modal">取消</button><button class="primary">儲存旅程</button></div></form>`);$('#trip-form').addEventListener('submit',ev=>{ev.preventDefault();const f=new FormData(ev.target),start=f.get('trip-start'),end=f.get('trip-end');if(end<start||data.events.some(e=>dateOf(e.startLocalDateTime)<start||dateOf(e.endLocalDateTime)>end)){$('#trip-error').classList.remove('hidden');$('#trip-error').textContent='旅程日期需要涵蓋所有現有行程，且結束日不能早於開始日。';return;}data.trip.name=f.get('trip-name').trim();data.trip.startDate=start;data.trip.endDate=end;closeModal();render();toast('旅程資料已儲存');});}
  function chooseZone(){showModal('選擇旅程主要時區',`<form class="field" id="zone-form"><p>變更時區後，行程輸入的當地日期與時間保持原樣。</p><select name="zone" aria-label="主要時區">${zoneOptions(data.trip.timeZoneId,false)}</select><div class="action-row"><button type="button" class="outline" data-action="close-modal">取消</button><button class="primary" type="submit">確認變更</button></div></form>`);$('#zone-form').addEventListener('submit',ev=>{ev.preventDefault();data.trip.timeZoneId=new FormData(ev.target).get('zone');closeModal();render();toast('旅程主要時區已更新');});}
  function minimalPdf(title,lines){const stream=`BT /F1 25 Tf 50 760 Td (${title}) Tj /F1 11 Tf ${lines.map(t=>`0 -28 Td (${t.replace(/[()\\]/g,' ')}) Tj`).join(' ')} ET`;const objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`];let out='%PDF-1.4\n',offsets=[0];objects.forEach((o,i)=>{offsets.push(out.length);out+=`${i+1} 0 obj\n${o}\nendobj\n`;});const xref=out.length;out+=`xref\n0 6\n0000000000 65535 f \n${offsets.slice(1).map(n=>`${String(n).padStart(10,'0')} 00000 n \n`).join('')}trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;return new TextEncoder().encode(out);}
  function seedFiles(){fileData={};fileData['files/museum-ticket/museum-demo.pdf']=minimalPdf('MUSEE DU LOUVRE - DEMO',['TABIframe fictional demonstration document','Paris / 14 June 2027 / 10:30','No reservation number. No personal information.','NOT VALID FOR ENTRY - DEMONSTRATION ONLY']);fileData['files/cruise-ticket/cruise-demo.pdf']=minimalPdf('SEINE CRUISE - DEMO',['TABIframe fictional demonstration document','Paris / 15 June 2027 / 18:30','No reservation number. No personal information.','NOT VALID FOR ENTRY - DEMONSTRATION ONLY']);fileData['files/museum-map/paris-walk.svg']=new TextEncoder().encode(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 700 540">${baseMap()}<text x="350" y="510" text-anchor="middle" fill="#567282" font-family="sans-serif" font-size="12">TABIframe / Fictional city walk / Demo only</text></svg>`);}
  function cleanExport(){const out=clone(data);for(const target of [...out.events,...out.dayNotes,...(out.dayReminders||[])])target.reminders=(target.reminders||[]).map(r=>{const runtime=reminderRuntime[r.id];if(runtime?.snoozed)return {id:r.id,kind:'ABSOLUTE',absoluteLocalDateTime:runtime.trigger,enabled:r.enabled!==false};return r;});for(const a of out.attachments){if(a.kind!=='URL'&&fileData[a.filePath])a.sizeBytes=fileData[a.filePath].length;else if(isMissing(a)){delete a.filePath;delete a.sizeBytes;delete a.sha256;}}return out;}
  async function sha256(bytes){if(!globalThis.crypto?.subtle)return null;const b=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('');}
  async function exportTrip(){try{const out=cleanExport(),files={},entries=[];for(const a of out.attachments)if(a.filePath&&fileData[a.filePath]){files[a.filePath]=fileData[a.filePath];const hash=await sha256(fileData[a.filePath]);if(hash)a.sha256=hash;entries.push({attachmentId:a.id,path:a.filePath,sizeBytes:files[a.filePath].length,sha256:hash||''});}const counts={events:out.events.length,dayNotes:out.dayNotes.length,accommodations:out.accommodations.length,attachments:out.attachments.length,reminders:[...out.events,...out.dayNotes,...(out.dayReminders||[])].reduce((n,t)=>n+(t.reminders||[]).length,0)};const manifest={format:'TABIframe',formatVersion:1,packageId:crypto.randomUUID?.()||id(),generatedAt:new Date().toISOString(),tripId:out.trip.id,tripName:out.trip.name,contentFile:'trip.json',counts,files:entries};files['manifest.json']=JSON.stringify(manifest,null,2);files['trip.json']=JSON.stringify(out,null,2);download(new Blob([TripZip.makeZip(files)],{type:'application/zip'}),`${out.trip.name.replace(/[\\/:*?"<>|]/g,'-')}.tabiframe`);toast('已匯出旅程；可用附件已帶入，缺失附件保留名稱');}catch(e){toast(`匯出失敗：${e.message}`);}}
  function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
  function validateTrip(raw){
    if(!raw||raw.formatVersion!==1||!raw.trip||!Array.isArray(raw.events)||!Array.isArray(raw.dayNotes)||!Array.isArray(raw.accommodations)||!Array.isArray(raw.attachments))throw new Error('需要 TABIframe v1 的 trip.json 或 .tabiframe 套件。');
    if(!raw.trip.id||!raw.trip.name||!/^\d{4}-\d{2}-\d{2}$/.test(raw.trip.startDate)||!/^\d{4}-\d{2}-\d{2}$/.test(raw.trip.endDate)||raw.trip.endDate<raw.trip.startDate)throw new Error('旅程名稱或日期不完整。');
    try{new Intl.DateTimeFormat('en',{timeZone:raw.trip.timeZoneId});}catch{throw new Error('旅程需要有效的 IANA 時區。');}
    if(raw.events.length>200||raw.attachments.length>100||Date.parse(raw.trip.endDate)-Date.parse(raw.trip.startDate)>59*86400000)throw new Error('互動展示支援 60 天、200 個行程與 100 個附件以內的旅程。');
    const ids=new Set();for(const [group,items] of Object.entries({events:raw.events,dayNotes:raw.dayNotes,accommodations:raw.accommodations,attachments:raw.attachments})){for(const item of items){if(!item||typeof item.id!=='string'||!/^[A-Za-z0-9_-]+$/.test(item.id)||ids.has(`${group}:${item.id}`))throw new Error('資料包含不正確或重複的 ID。');ids.add(`${group}:${item.id}`);if(group==='events'){if(!categories[item.category]||!['FIXED','FLEXIBLE'].includes(item.flexibility)||validateEvent(item))throw new Error('行程名稱、時間或分類不正確。');if(dateOf(item.startLocalDateTime)<raw.trip.startDate||dateOf(item.endLocalDateTime)>raw.trip.endDate)throw new Error('行程時間必須在旅程日期範圍內。');}if(group==='attachments'){if(!['URL','PDF','IMAGE'].includes(item.kind)||!item.displayName)throw new Error('附件資料不完整。');if(item.kind==='URL'&&!safeUrl(item.url))throw new Error('附件網址需使用 http 或 https。');if(item.filePath&&!/^files\/[A-Za-z0-9_-]+\/[^/\\]+$/.test(item.filePath))throw new Error('附件路徑格式不正確。');}if(item.location){for(const [key,max]of [['latitude',90],['longitude',180]])if(item.location[key]!=null&&(!Number.isFinite(item.location[key])||Math.abs(item.location[key])>max))throw new Error('地點座標超出範圍。');}for(const r of item.reminders||[]){if(!r.id||!['RELATIVE','ABSOLUTE'].includes(r.kind)||r.kind==='ABSOLUTE'&&!Number.isFinite(naive(r.absoluteLocalDateTime||''))||r.kind==='RELATIVE'&&(!Number.isFinite(r.offsetMinutes)||r.offsetMinutes<0))throw new Error('提醒資料不正確。');}}}
    return clone(raw);
  }
  async function readImport(file){if(!file)return;try{if(file.size>30*1024*1024)throw new Error('展示版支援 30 MB 以內的檔案。');let raw,files={};if(file.name.endsWith('.json'))raw=JSON.parse(await file.text());else{files=await TripZip.readZip(await file.arrayBuffer());if(!files['trip.json'])throw new Error('套件缺少 trip.json。');if(!files['manifest.json'])throw new Error('套件缺少 manifest.json。');const manifest=JSON.parse(new TextDecoder().decode(files['manifest.json']));if(manifest.format!=='TABIframe'||manifest.formatVersion!==1)throw new Error('套件格式版本不支援。');raw=JSON.parse(new TextDecoder().decode(files['trip.json']));}const validated=validateTrip(raw);for(const a of validated.attachments)if(a.sha256&&files[a.filePath]){const hash=await sha256(files[a.filePath]);if(hash&&hash!==a.sha256)throw new Error(`附件 ${a.displayName} 的雜湊驗證失敗。`);}previewImport(validated,files);}catch(e){showModal('無法匯入',`<p class="inline-error">${escape(e.message)}</p><p>請選擇符合 TABIframe v1 的旅程檔，或先用內建示範旅程。</p><button class="primary block" data-action="close-modal">知道了</button>`,true);}}
  function previewImport(next,files={}){importPending={data:next,files};const missing=next.attachments.filter(a=>a.kind!=='URL'&&!files[a.filePath]);showModal('匯入預覽',`<div class="data-preview"><h4>${escape(next.trip.name)}</h4><p>${next.trip.startDate} – ${next.trip.endDate}<br>${escape(next.trip.timeZoneId)}</p><div class="metrics">${[[next.events.length,'行程'],[next.accommodations.length,'住宿'],[next.attachments.length,'附件']].map(([n,l])=>`<div class="metric"><b>${n}</b>${l}</div>`).join('')}</div>${missing.length?`<div class="info-banner" style="background:#fff4df;color:#ac721d">${icon('info')}${missing.length} 個附件缺少實體檔案，匯入後可以重新連結。</div>`:''}<p>確認後會以這份旅程取代目前展示內容。想保留剛才的修改，可以先匯出。</p><div class="action-row"><button class="outline" data-action="close-modal">取消</button><button class="primary" data-action="confirm-import">確認取代</button></div></div>`);}
  function demoImport(){const next=createSeed();next.trip.id='paris-weekend-demo';next.trip.name='巴黎週末・另一種步調';next.events=next.events.filter(e=>['orsay','picnic','tower','cruise'].includes(e.id));next.trip.startDate='2027-06-15';next.trip.endDate='2027-06-16';next.dayNotes=next.dayNotes.filter(n=>n.date>='2027-06-15');next.dayNotes[0].text='換一份旅程資料，原本熟悉的畫面就能繼續使用。';next.attachments=next.attachments.filter(a=>['museum-map','cruise-ticket','eiffel-web'].includes(a.id));next.accommodations[0].startDateInclusive='2027-06-15';previewImport(next,cloneFileData());}
  function cloneFileData(){return Object.fromEntries(Object.entries(fileData).map(([k,v])=>[k,v.slice()]));}
  function acceptImport(){if(!importPending)return;data=importPending.data;fileData=Object.fromEntries(Object.entries(importPending.files).filter(([k])=>k.startsWith('files/')));Object.values(attachmentUrls).forEach(URL.revokeObjectURL);attachmentUrls={};reminderRuntime={};selectedDate=data.trip.startDate;now=`${selectedDate}T10:10`;scrolls={};history=[];importPending=null;closeModal();screen='trip';render('forward');toast('新旅程已匯入，展示內容已取代');}
  function showHelp(){showModal('從這裡開始體驗',`<div class="tour-checklist"><div><b>01 · 手機內可以直接操作</b><br>底部導覽列、行程、日期、鈴鐺與地圖都能點選。</div><div><b>02 · 日期與位置彼此相連</b><br>在地圖換日期，回到時間軸還是同一天。</div><div><b>03 · 長按後再拖動</b><br>按住色塊 0.5 秒解鎖，放手後確認；快速滑動會瀏覽時間軸。</div><div><b>04 · 通知使用展示時間</b><br>目前固定在 ${niceDate(dateOf(now))} ${timeOf(now)}。可觸發通知或前進 5 分鐘，不會向裝置發送系統通知。</div><div><b>05 · 全部都是虛構資料</b><br>編輯只保留在這個分頁，按「重新體驗」就能還原。匯出的 .tabiframe 是真正旅程檔。</div><div><b>06 · 地圖為功能示意</b><br>地點可聚焦與縮放；導航會另外詢問是否開啟 Google Maps。</div></div><button class="primary block" data-action="close-modal">開始探索</button>`);}
  function showDragHint(){requestAnimationFrame(()=>{const area=$('.timeline-area');if(!area)return;const hint=document.createElement('div');hint.className='timeline-drag-hint';hint.innerHTML=`${icon('move')}長按 0.5 秒，解鎖移動`;area.append(hint);setTimeout(()=>hint.remove(),4000);});}
  function playDragDemo(){
    screen='timeline';selectedEvent=null;const event=eventsFor().find(e=>e.flexibility==='FLEXIBLE')||eventsFor()[0];if(!event){toast('今天還沒有可以示範的行程');return;}
    scrolls[selectedDate]=Math.max(0,TOP+minute(event.startLocalDateTime)*HOUR/60-110);render();
    const card=$$('.event-card').find(c=>c.dataset.event===event.id);if(!card)return;
    $('.stay-float')?.classList.add('hidden');$('#stage-caption').textContent='長按 0.5 秒，解鎖行程色塊…';
    setTimeout(async()=>{if(!card.isConnected)return;card.classList.add('dragging');$('#stage-caption').textContent='上下拖動，放手後確認新時間';await card.animate([{transform:'translateY(0)'},{transform:`translateY(${HOUR/2}px)`}],{duration:750,easing:'cubic-bezier(.2,.6,.2,1)',fill:'forwards'}).finished.catch(()=>{});if(!card.isConnected)return;movePending={id:event.id,delta:30};render();showMoveDialog();$('#stage-caption').textContent=chapters[chapter].caption;},500);
  }
  function nowShortcut(){selectedDate=dateOf(now);screen='timeline';selectedEvent=null;scrolls[selectedDate]=Math.max(0,TOP+minute(now)*HOUR/60-170);history=[];closeModal();render();toast(`已移到 ${shortDate(selectedDate)} ${timeOf(now)}`);}
  function reset(){showModal('重新體驗？','<p>將還原虛構巴黎旅程，清除這個分頁中的修改。</p><div class="action-row"><button class="outline" data-action="close-modal">取消</button><button class="primary" data-action="confirm-reset">重新開始</button></div>',true);}
  function doReset(){Object.values(attachmentUrls).forEach(URL.revokeObjectURL);attachmentUrls={};data=createSeed();profile='Alex';selectedDate=data.trip.startDate;now='2027-06-14T10:10';scrolls={};history=[];reminderRuntime={'r-note':{status:'FIRED'}};noteExpanded=true;draft=null;undo=null;attachmentFilter='all';reminderFilter='all';searchQuery='';seedFiles();closeModal();hideNotification();setChapter(0);toast('已還原巴黎三日示範旅程');}
  function execute(action,el){
    switch(action){
      case 'back':back();break;
      case 'close-modal':closeModal();break;
      case 'open-map':go('map');break;
      case 'open-reminders':go('reminders');break;
      case 'now':case 'nav-now':nowShortcut();break;
      case 'nav-timeline':case 'nav-search':case 'nav-attachments':case 'nav-trip':saveScroll();screen=action.slice(4);selectedEvent=null;history=[];render();break;
      case 'toggle-note':saveScroll();noteExpanded=!noteExpanded;render();break;
      case 'note':openNote();break;
      case 'note-reminder':reminderEditor('note');break;
      case 'stay':stayEditor();break;
      case 'navigate-stay':navigate(stayFor()?.location);break;
      case 'navigate-event':navigate(eventById(selectedEvent)?.location);break;
      case 'add-event':startEditor();break;
      case 'edit-event':startEditor(eventById(selectedEvent));break;
      case 'edit-demo':{const e=eventsFor()[0];if(e)startEditor(e);break;}
      case 'drag-demo':playDragDemo();break;
      case 'cancel-move':movePending=null;closeModal();render();break;
      case 'confirm-move':{const e=eventById(movePending?.id);if(e){e.startLocalDateTime=shift(e.startLocalDateTime,movePending.delta);e.endLocalDateTime=shift(e.endLocalDateTime,movePending.delta);}movePending=null;closeModal();screen='timeline';selectedEvent=null;render();toast('新時間已儲存，提醒也會跟著調整');break;}
      case 'delete-event':deleteEvent();break;
      case 'confirm-delete-event':{const e=eventById(selectedEvent);if(!e)break;undo={event:clone(e),index:data.events.indexOf(e)};data.events=data.events.filter(x=>x.id!==e.id);closeModal();screen='timeline';selectedEvent=null;history=[];render();toast(`已刪除「${e.title}」`,{label:'復原',key:'undo-delete'});break;}
      case 'undo-delete':if(undo){data.events.splice(undo.index,0,undo.event);const title=undo.event.title;undo=null;render();toast(`已復原「${title}」`);}break;
      case 'clock-start':openClock('start');break;
      case 'clock-end':openClock('end');break;
      case 'save-clock':{const input=$('#clock-time');if(!input.value)break;const key=el.dataset.endpoint==='start'?'startLocalDateTime':'endLocalDateTime';draft.event[key]=`${dateOf(draft.event[key])}T${input.value}`;const value=input.value;closeModal();$(`#clock-${el.dataset.endpoint}-value`).innerHTML=`${icon('clock')}${value}`;break;}
      case 'pick-location':pickLocation();break;
      case 'editor-attachment':pickAttachments(true);break;
      case 'pick-attachment':pickAttachments(false);break;
      case 'ticket':{const a=attachmentById(eventById(selectedEvent)?.attachmentIds?.[0]);if(a)go('attachment',{eid:a.id});break;}
      case 'quick-reminder':quickReminder();break;
      case 'reminder-editor':reminderEditor();break;
      case 'reminder-demo':{const e=eventsFor().find(e=>naive(e.startLocalDateTime)>naive(now))||eventsFor()[0];if(e)reminderEditor('event',e.id);break;}
      case 'notify':notify();break;
      case 'hide-notification':hideNotification();break;
      case 'advance':advance();break;
      case 'cleanup-reminders':showModal('清理提醒紀錄？',`<p>會移除 ${allReminders().filter(cleanupReminder).length} 筆已過期、已通知或停用的紀錄。等待中的提醒會保留。</p><div class="action-row"><button class="outline" data-action="close-modal">取消</button><button class="primary" data-action="confirm-cleanup">確認清理</button></div>`,true);break;
      case 'confirm-cleanup':allReminders().filter(cleanupReminder).forEach(m=>removeReminder(m.r.id));closeModal();render();toast('提醒紀錄已清理');break;
      case 'clear-search':searchQuery='';render();$('#search-input').focus();break;
      case 'search-demo':searchQuery='羅浮宮';screen='search';selectedEvent=null;render();break;
      case 'search-all':searchQuery='巴黎';screen='search';selectedEvent=null;render();break;
      case 'ticket-demo':go('attachment',{eid:data.attachments.find(a=>a.id==='museum-ticket')?.id||data.attachments[0]?.id});break;
      case 'missing-demo':screen='attachments';attachmentFilter='missing';render();break;
      case 'add-file':$('#attachment-file').dataset.relink='';$('#attachment-file').click();break;
      case 'add-url':addUrl();break;
      case 'delete-attachment':{const a=attachmentById(selectedEvent);showModal('刪除附件？',`<p>會從附件庫與關聯行程移除「${escape(a.displayName)}」。</p><div class="action-row"><button class="outline" data-action="close-modal">取消</button><button class="primary" data-action="confirm-delete-attachment">刪除附件</button></div>`,true);break;}
      case 'confirm-delete-attachment':{const aid=selectedEvent,a=attachmentById(aid);data.attachments=data.attachments.filter(x=>x.id!==aid);for(const target of [...data.events,...data.accommodations])target.attachmentIds=(target.attachmentIds||[]).filter(x=>x!==aid);if(a?.filePath)delete fileData[a.filePath];if(attachmentUrls[aid])URL.revokeObjectURL(attachmentUrls[aid]);delete attachmentUrls[aid];closeModal();screen='attachments';selectedEvent=null;render();toast('附件已刪除');break;}
      case 'map-overview':if(screen!=='map'){screen='map';render();}mapFocus=null;mapScale=1;mapPan={x:0,y:0};updateMap();break;
      case 'map-first':if(screen!=='map'){screen='map';render();}if(eventsFor()[0])focusMap(eventsFor()[0].id);break;
      case 'map-in':mapScale=Math.min(5,mapScale*1.35);updateMap();break;
      case 'map-out':mapScale=Math.max(.8,mapScale/1.35);updateMap();break;
      case 'time-zone':chooseZone();break;
      case 'add-stay':{showModal('新增住宿','<p>請為新住宿設定名稱與日期。</p><button class="primary block" data-action="new-stay-form">繼續</button>');break;}
      case 'new-stay-form':stayEditor('__new__');break;
      case 'edit-trip':editTrip();break;
      case 'export':exportTrip();break;
      case 'import':showModal('匯入旅程','<p>選擇 .tabiframe 或 trip.json，在確認預覽後取代目前內容。</p><button class="primary block" data-action="choose-trip-file">'+icon('import')+'選擇旅程檔</button><button class="secondary block" data-action="import-demo" style="margin-top:10px">用虛構新旅程體驗</button>');break;
      case 'choose-trip-file':$('#trip-file').click();break;
      case 'import-demo':demoImport();break;
      case 'confirm-import':acceptImport();break;
      case 'confirm-reset':doReset();break;
    }
  }
  document.addEventListener('click',ev=>{
    const el=ev.target.closest('button,a,[role="button"]');
    if(ev.target.matches('.scrim')){closeModal();return;}
    if(!el)return;
    if(el.dataset.chapter!=null){setChapter(Number(el.dataset.chapter));return;}
    if(el.dataset.action){execute(el.dataset.action,el);return;}
    if(el.dataset.favorite){ev.stopPropagation();const a=attachmentById(el.dataset.favorite);if(a){a.favorite=!a.favorite;const scroll=$('.page-scroll,.tabs-content')?.scrollTop;render();const body=$('.page-scroll,.tabs-content');if(body)body.scrollTop=scroll;}return;}
    if(el.dataset.event){if(performance.now()<suppressClickUntil)return;openEvent(el.dataset.event);return;}
    if(el.dataset.date){selectDate(el.dataset.date);return;}
    if(el.dataset.category){collectDraft();draft.event.category=el.dataset.category;$$('[data-category]').forEach(x=>x.classList.toggle('selected',x===el));return;}
    if(el.dataset.flexibility){collectDraft();draft.event.flexibility=el.dataset.flexibility;$$('[data-flexibility]').forEach(x=>x.classList.toggle('selected',x===el));return;}
    if(el.dataset.attachment){go('attachment',{eid:el.dataset.attachment});return;}
    if(el.dataset.attachmentFilter){attachmentFilter=el.dataset.attachmentFilter;render();return;}
    if(el.dataset.reminderFilter){reminderFilter=el.dataset.reminderFilter;render();return;}
    if(el.dataset.deleteReminder){removeReminder(el.dataset.deleteReminder);render();toast('提醒已刪除');return;}
    if(el.dataset.toggleReminder){const m=allReminders().find(m=>m.r.id===el.dataset.toggleReminder);if(m){m.r.enabled=m.r.enabled===false;render();if(m.r.enabled&&!activeReminder(m))toast('原時間已過；可按「延後 5 分」重新排程。');}return;}
    if(el.dataset.snooze){snooze(el.dataset.snooze,Number(el.dataset.delay));return;}
    if(el.dataset.reminderOpen){openReminderTarget(el.dataset.reminderOpen);return;}
    if(el.dataset.result){const key=el.dataset.result,rid=el.dataset.resultId;if(key==='event')openEvent(rid);if(key==='attachment')go('attachment',{eid:rid});if(key==='stay')stayEditor(rid);if(key==='note'){selectedDate=data.dayNotes.find(n=>n.id===rid).date;go('timeline');openNote();}return;}
    if(el.dataset.search){searchQuery=el.dataset.search;render();return;}
    if(el.dataset.mapPoint){focusMap(el.dataset.mapPoint);return;}
    if(el.dataset.mapRow){focusMap(el.dataset.mapRow);return;}
    if(el.dataset.navigate){const rid=el.dataset.navigate;const item=rid.startsWith('stay:')?data.accommodations.find(s=>s.id===rid.slice(5)):eventById(rid);navigate(item?.location);return;}
    if(el.dataset.external){openExternal(el.dataset.external);return;}
    if(el.dataset.relink){$('#attachment-file').dataset.relink=el.dataset.relink;$('#attachment-file').click();return;}
    if(el.dataset.downloadAttachment){const a=attachmentById(el.dataset.downloadAttachment);if(a&&fileData[a.filePath])download(new Blob([fileData[a.filePath]],{type:a.kind==='IMAGE'?'image/svg+xml':'application/pdf'}),a.fileName||'attachment.pdf');return;}
    if(el.dataset.stay){stayEditor(el.dataset.stay);return;}
    if(el.dataset.deleteStay){const sid=el.dataset.deleteStay;showModal('刪除住宿？',`<p>會移除這份住宿資料。</p><div class="action-row"><button class="outline" data-action="close-modal">取消</button><button class="primary" data-remove-stay="${escape(sid)}">確認刪除</button></div>`,true);return;}
    if(el.dataset.removeStay){data.accommodations=data.accommodations.filter(s=>s.id!==el.dataset.removeStay);closeModal();render();toast('住宿已刪除');}
  });
  document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){if(modal)closeModal();else if(notification)hideNotification();else if(!['timeline','search','attachments','trip'].includes(screen))back();}if((ev.key==='Enter'||ev.key===' ')&&ev.target.getAttribute('role')==='button'&&!ev.target.matches('button,a')){ev.preventDefault();ev.target.click();}});
  document.addEventListener('pointermove',dragMove,{passive:false});document.addEventListener('pointerup',dragEnd);document.addEventListener('pointercancel',ev=>dragEnd(ev,true));
  $('#reset-demo').addEventListener('click',reset);$('#show-help').addEventListener('click',showHelp);$('#previous-chapter').addEventListener('click',()=>setChapter(chapter-1));$('#next-chapter').addEventListener('click',()=>setChapter(chapter+1));
  $('#trip-file').addEventListener('change',ev=>{const file=ev.target.files[0];ev.target.value='';readImport(file);});
  $('#attachment-file').addEventListener('change',async ev=>{
    const file=ev.target.files[0],relink=ev.target.dataset.relink;ev.target.value='';if(!file)return;
    if(file.size>10*1024*1024){toast('展示版支援 10 MB 以內的附件');return;}
    if(file.type!=='application/pdf'&&!file.type.startsWith('image/')){toast('請選擇 PDF 或圖片');return;}
    const kind=file.type==='application/pdf'?'PDF':'IMAGE',existing=relink?attachmentById(relink):null;
    if(existing&&existing.kind!==kind){toast(`這份附件需要 ${existing.kind} 格式，請重新選擇。`);return;}
    const aid=existing?.id||id(),filename=file.name.replace(/[/\\]/g,'-'),path=`files/${aid}/${filename}`,bytes=new Uint8Array(await file.arrayBuffer());
    if(existing?.filePath)delete fileData[existing.filePath];fileData[path]=bytes;
    if(attachmentUrls[aid])URL.revokeObjectURL(attachmentUrls[aid]);delete attachmentUrls[aid];
    if(existing){existing.fileName=filename;existing.filePath=path;existing.sizeBytes=bytes.length;delete existing.sha256;}else{data.attachments.push({id:aid,displayName:filename,kind,fileName:filename,filePath:path,favorite:false,sensitive:false,sizeBytes:bytes.length});if(screen==='detail'){const e=eventById(selectedEvent);(e.attachmentIds??=[]).push(aid);}}
    render();toast(existing?'附件已重新連結':'附件已加入');
  });
  function fitPhone(){const small=innerWidth<=760,available=small?Math.min(innerWidth-67,400):Math.max(270,$('.demo-stage').clientWidth-43),height=Math.max(515,innerHeight-165);const scale=small?Math.min(.84,available/400):document.body.classList.contains('large-preview')?Math.min(1,available/400):Math.min(1,available/400,height/840)*.92;document.documentElement.style.setProperty('--scale',scale.toFixed(4));}
  $('#preview-size').addEventListener('click',()=>{const large=document.body.classList.toggle('large-preview');$('#preview-size').textContent=large?'適合視窗 ↙':'放大畫面 ↗';fitPhone();});
  addEventListener('resize',fitPhone);addEventListener('hashchange',()=>{const i=chapters.findIndex(c=>`#${c.key}`===window.location.hash);if(i>=0)setChapter(i,true);});
  seedFiles();const initial=chapters.findIndex(c=>`#${c.key}`===window.location.hash);setChapter(Math.max(0,initial),true);fitPhone();
